def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive.append(opp)

    # If no opponents alive, conserve
    if not alive:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = float(my_status.get('no_water_days', 0.0))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent aggression
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Supply pressure: more supply -> can bid less; less supply -> bid more
    # Normalize supply to [0,1] where 0 means MIN_SUPPLY, 1 means MAX_SUPPLY
    s = float(supply)
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (s - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_factor < 0.0:
        supply_factor = 0.0
    if supply_factor > 1.0:
        supply_factor = 1.0

    # Base bid target: try to slightly undercut the highest yesterday bid to win allocation
    # but avoid wasting budget.
    # If David-like overbidding occurred (high max), we lean toward a controlled bid.
    aggression = 0.0
    if highest_prev_bid > 0.0:
        aggression = highest_prev_bid / (DAILY_SALARY * 1.15)
    if aggression < 0.0:
        aggression = 0.0
    if aggression > 1.5:
        aggression = 1.5

    # Need-based urgency
    urgency = 0.0
    if my_hp <= 2.0:
        urgency = 1.0
    elif my_hp <= 4.0:
        urgency = 0.7
    else:
        urgency = 0.3

    if my_no_water_days >= 2.0:
        urgency = max(urgency, 0.8)
    elif my_no_water_days >= 1.0:
        urgency = max(urgency, 0.55)

    # Compute target multiplier
    # Lower supply -> higher multiplier; higher aggression -> slightly higher bid to beat them.
    # We aim around 0.45~0.95 of DAILY_SALARY depending on urgency and supply.
    base_mult = 0.55 + (1.0 - supply_factor) * 0.25
    base_mult += (aggression - 0.5) * 0.15
    if base_mult < 0.35:
        base_mult = 0.35
    if base_mult > 1.0:
        base_mult = 1.0

    # If yesterday highest bid was extremely high, cap our bid just under it
    # (assumption: opponent continues aggressive but we can win with less).
    undercut_cap = highest_prev_bid - 1.0 if highest_prev_bid > 1.0 else DAILY_SALARY * 0.9

    target = DAILY_SALARY * base_mult * (0.75 + 0.5 * urgency)
    # Apply undercut cap
    if target > undercut_cap:
        target = undercut_cap

    # If we are in critical state, push closer to cap
    if urgency >= 0.8:
        target = max(target, DAILY_SALARY * 0.85)
        if highest_prev_bid > 0.0:
            # still try to not exceed highest_prev_bid by too much
            target = min(target, highest_prev_bid)

    # Ensure within budget; also keep non-negative
    if my_budget <= 0.0:
        return 0.0

    bid = float(min(my_budget, max(0.0, target)))

    # Small day-based jitter to avoid ties (bounded)
    try:
        jitter = ((int(day) % 7) - 3) * 0.5
    except Exception:
        jitter = 0.0
    bid = float(max(0.0, min(my_budget, bid + jitter)))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    my_units = int(supply // WATER_REQ)
    total_players = 1 + len(alive)

    prev_bids = []
    david_prev = None
    alex_prev = None
    pressure = 0.0
    needy_opponents = 0

    for oid, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            needy_opponents += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > pressure:
                pressure = float(bid)
        if oid == 'David' and bid is not None:
            david_prev = float(bid)
        if oid == 'Alex' and bid is not None:
            alex_prev = float(bid)

    if not alive:
        return float(min(budget, 20.0))

    scarcity = my_units < total_players
    very_tight = my_units <= 1

    if hp <= 2 or no_water_days >= 2:
        base = 88.0
    elif hp <= 4 or no_water_days >= 1:
        base = 74.0
    else:
        if not scarcity:
            base = 36.0
        elif very_tight:
            base = 79.0
        else:
            base = 58.0

    if needy_opponents >= 2:
        base += 6.0

    if david_prev is not None:
        if david_prev >= 100:
            if hp >= 5 and budget < 300:
                base = min(base, 54.0)
            else:
                base = max(base, 82.0)
        elif david_prev >= 88:
            base = max(base, 76.0)

    if alex_prev is not None and scarcity:
        target = alex_prev + 2.0
        if target > base:
            base = target

    if pressure >= 85 and hp >= 5 and budget < 220:
        base = min(base, 52.0)

    if day >= 8:
        if hp >= 5:
            base += 6.0
        else:
            base += 12.0

    reserve = 0.0
    if hp >= 5:
        reserve = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_affordable = max(0.0, budget - reserve)
    bid = min(base, max_affordable)

    if hp <= 2:
        bid = min(max(bid, 89.0), budget)
    elif scarcity and pressure > 0 and hp <= 4:
        bid = min(max(bid, pressure + 1.5), budget)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

