def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.98
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.85
    elif my_hp <= 7:
        base_bid = DAILY_SALARY * 0.7

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 2)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid + 1)
        else:
            base_bid = max(base_bid, highest_prev_bid * 1.1)

    total_water_units_available = int(current_supply // WATER_REQ)
    total_agents_needing_water = num_alive_opponents + 1

    if total_water_units_available < total_agents_needing_water:
        base_bid = max(base_bid, DAILY_SALARY * 0.75)
        if my_hp <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.99)
    elif total_water_units_available >= total_agents_needing_water:
        if my_hp > 7:
            base_bid = min(base_bid, DAILY_SALARY * 0.4)
        else:
            base_bid = min(base_bid, DAILY_SALARY * 0.6)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_hp > 0:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 4 and my_hp > 0 and my_budget < DAILY_SALARY * (remaining_days + 1) * 0.7:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)

    final_bid = min(my_budget, base_bid)

    if my_hp < 10 and my_budget > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.1)
    elif my_hp == 10:
        if total_water_units_available >= total_agents_needing_water:
            final_bid = min(my_budget, DAILY_SALARY * 0.05)
        else:
            final_bid = min(my_budget, DAILY_SALARY * 0.3)

    return final_bid
